<?php require_once '../config.php';require_admin();if(isset($_GET['del'])){db()->prepare('DELETE FROM collections WHERE id=?')->execute([(int)$_GET['del']]);header('Location: collections.php');exit;}if($_SERVER['REQUEST_METHOD']==='POST'){ $id=(int)($_POST['id']??0);$img=upload_image('image','uploads');if($id){$sql='UPDATE collections SET name=?,slug=?,description=?,visible=?'.($img?',image=?':'').' WHERE id=?';$a=[$_POST['name'],slug($_POST['name']),$_POST['description'],isset($_POST['visible'])?1:0];if($img)$a[]=$img;$a[]=$id;db()->prepare($sql)->execute($a);}else{db()->prepare('INSERT INTO collections(name,slug,description,visible,image) VALUES(?,?,?,?,?)')->execute([$_POST['name'],slug($_POST['name']),$_POST['description'],1,$img]);}header('Location: collections.php');exit;}$edit=null;if(isset($_GET['edit'])){$q=db()->prepare('SELECT * FROM collections WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}$rows=db()->query('SELECT * FROM collections ORDER BY sort_order,id')->fetchAll();?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><link rel="stylesheet" href="../assets/style.css"></head><body><div class="adminwrap"><a href="dashboard.php">← Dashboard</a><h1>Koleksiyonlar</h1><form class="admin" method="post" enctype="multipart/form-data"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><input name="name" required placeholder="Koleksiyon adı" value="<?=e($edit['name']??'')?>"><textarea name="description" placeholder="Açıklama"><?=e($edit['description']??'')?></textarea><input type="file" name="image"><label><input type="checkbox" name="visible" <?=!isset($edit)||$edit['visible']?'checked':''?>> Yayında</label><br><br><button class="btn">Kaydet</button></form><br><table><tr><th>Ad</th><th>Durum</th><th>İşlem</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=($r['visible']?'Yayında':'Gizli')?></td><td><a href="?edit=<?=$r['id']?>">Düzenle</a> · <a href="?del=<?=$r['id']?>" onclick="return confirm('Silinsin mi?')">Sil</a></td></tr><?php endforeach;?></table></div></body></html>
